begin; select set_config('request.jwt.claim.sub','7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d',true); select set_config('request.jwt.claims','{"sub":"7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d","role":"authenticated"}',true); do $$ begin if not exists(select 1 from schoolpro_schools where id='d342eb87-8d6a-477a-a380-7fab83f586b7' and owner_id='7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d' and name='IHLINK ACADEMY (Testing)')then raise exception 'Testing Academy only';end if;end $$;

insert into schoolpro_library_books(id,school_id,title,author,isbn,copies,available_copies)
select md5('ihlink-academy-test-v1:book:'||n)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7',(array['Early Readers','Number Adventures','Basic English Practice','Science Around Us','Nigerian Social Studies','Junior Mathematics','Computer Skills','Biology Workbook','Chemistry Practice','Physics Examples'])[1+(n-1)%10]||' — TEST volume '||n,'IHLink Academy sample library','TEST-BOOK-'||n,20,20 from generate_series(1,30)n on conflict(id)do nothing;
do $$ declare s record;book uuid;l uuid;n integer;begin for s in select * from schoolpro_students where school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and admission_number like 'IH-TST-2026-%' and right(admission_number,3)::int<=6 loop n:=right(s.admission_number,3)::int;book:=md5('ihlink-academy-test-v1:book:'||(1+mod(abs(hashtext(s.class_name))::bigint,28)))::uuid;if not exists(select 1 from schoolpro_library_loans where school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and student_id=s.id)then l:=borrow_schoolpro_library_book(book,s.id,null,now()+case when n%3=0 then interval '-7 days' else interval '14 days' end);if n%3=1 then perform return_schoolpro_library_book(l,0);end if;end if;end loop;end $$;
insert into schoolpro_health_records(id,school_id,student_id,recorded_at,complaint,assessment,treatment,disposition,status,follow_up_date,follow_up_notes)
select md5('ihlink-academy-test-v1:clinic:'||s.id)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7',s.id,'2026-05-05 10:00+00',case when right(admission_number,3)::int=6 then 'TEST: headache after outdoor activity' else 'TEST: minor playground scrape' end,'Fictional school-clinic encounter, no diagnosis for a real person','Sample first-aid and guardian-contact record','Returned to class',case when right(admission_number,3)::int=6 then 'follow-up' else 'closed' end,case when right(admission_number,3)::int=6 then date '2026-05-06' else null end,'TEST: reviewed by school nurse' from schoolpro_students s where school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and admission_number like 'IH-TST-2026-%' and right(admission_number,3)::int in(6,7) on conflict(id)do nothing;
insert into schoolpro_transport_routes(id,school_id,name,vehicle,driver_name,driver_phone,fee)
select md5('ihlink-academy-test-v1:route:'||n)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7','TEST: Academy route '||n,'School bus '||n,'Test Driver '||n,'',4500+n*500 from generate_series(1,4)n on conflict(id)do nothing;
insert into schoolpro_student_transport(id,school_id,student_id,route_id,pickup_point,active)
select md5('ihlink-academy-test-v1:transport:'||id)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7',id,md5('ihlink-academy-test-v1:route:'||(1+right(admission_number,3)::int%4))::uuid,'TEST: designated school pickup point',right(admission_number,3)::int<>10 from schoolpro_students where school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and admission_number like 'IH-TST-2026-%' and right(admission_number,3)::int in(8,9,10) on conflict(id)do nothing;
insert into schoolpro_hostel_rooms(id,school_id,hostel_name,room,capacity,occupied,fee)
select md5('ihlink-academy-test-v1:room:'||n)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7','TEST: Senior hostel','Room '||n,10,0,15000 from generate_series(1,4)n on conflict(id)do nothing;
insert into schoolpro_hostel_allocations(id,school_id,student_id,room_id,session,active)
select md5('ihlink-academy-test-v1:hostel:'||s.id)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7',s.id,md5('ihlink-academy-test-v1:room:'||(1+right(admission_number,3)::int%4))::uuid,'2025/2026',true from schoolpro_students s join schoolpro_classes c on c.id=s.class_id where s.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and s.admission_number like 'IH-TST-2026-%' and c.level='senior_secondary' and right(s.admission_number,3)::int in(11,12,13,14) on conflict(id)do nothing;
update schoolpro_hostel_rooms r set occupied=(select count(*) from schoolpro_hostel_allocations a where a.room_id=r.id and a.active) where r.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and r.hostel_name like 'TEST:%';
insert into schoolpro_inventory_assets(id,school_id,name,category,quantity,condition,location)
select md5('ihlink-academy-test-v1:asset:'||n)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7','TEST: '||(array['Desk','Chair','Whiteboard','Laptop','Projector','Sports kit','Science kit','First-aid box'])[1+(n-1)%8],(array['Furniture','Furniture','Teaching','ICT','ICT','Sports','Laboratory','Clinic'])[1+(n-1)%8],5+n,case when n%5=0 then 'Needs repair' else 'Good' end,'Academy test room '||n from generate_series(1,16)n on conflict(id)do nothing;
insert into schoolpro_leave_requests(id,school_id,member_id,leave_type,start_date,end_date,reason,status)
select md5('ihlink-academy-test-v1:leave:'||n)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7',md5('ihlink-academy-test-v1:member:'||n)::uuid,case when n%2=0 then 'Training' else 'Personal' end,'2026-06-01','2026-06-03','TEST: staff leave workflow example','pending' from generate_series(1,12)n on conflict(id)do nothing;
do $$ declare r record;begin for r in select id from schoolpro_leave_requests where school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and reason like 'TEST:%' and status='pending' and member_id in(select md5('ihlink-academy-test-v1:member:'||n)::uuid from generate_series(1,8)n) loop perform review_schoolpro_leave(r.id,case when r.id in(select md5('ihlink-academy-test-v1:leave:'||n)::uuid from generate_series(1,4)n)then 'approved' else 'rejected' end);end loop;end $$;
insert into schoolpro_payroll_records(id,school_id,member_id,period,gross,deductions,status)
select md5('ihlink-academy-test-v1:payroll:'||m.id||':'||period)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7',m.id,period,65000+1000*row_number()over(order by m.id),2500,'draft' from schoolpro_members m cross join unnest(array['TEST 2026-05','TEST 2026-06','TEST 2026-07'])period where m.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and m.id in(select md5('ihlink-academy-test-v1:member:'||n)::uuid from generate_series(1,39)n) on conflict(id)do nothing;
update schoolpro_payroll_records set status='approved' where school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and period in('TEST 2026-05','TEST 2026-06') and status='draft';
update schoolpro_payroll_records set status='paid',payment_reference='TEST-SIMULATED-PAYROLL-'||id where school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and period='TEST 2026-05' and status='approved';
insert into schoolpro_discipline_records(id,school_id,student_id,incident,action_taken,status,created_by)
select md5('ihlink-academy-test-v1:discipline:'||s.id)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7',s.id,'TEST: repeated lateness to class','Class teacher discussed punctuality; leadership to review and contact guardian if needed',case when right(admission_number,3)::int=15 then 'open' else 'resolved' end,m.user_id from schoolpro_students s join schoolpro_subject_assignments a on a.class_id=s.class_id and a.session='2025/2026' join schoolpro_members m on m.id=a.teacher_member_id where s.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and s.admission_number like 'IH-TST-2026-%' and right(s.admission_number,3)::int in(15,16) and a.subject_id=md5('ihlink-academy-test-v1:subject:'||(select g from generate_series(1,28)g where md5('ihlink-academy-test-v1:class:'||g)::uuid=s.class_id)||':2')::uuid on conflict(id)do nothing;
insert into schoolpro_calendar_events(id,school_id,title,event_date,event_type,details) values(md5('ihlink-academy-test-v1:calendar:1')::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7','TEST: First Term teaching calendar','2025-09-15','academic','Twelve teaching weeks with revision and examinations; historical test session.') on conflict(id)do nothing;
